INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','easy','flashcard','What PEFR threshold defines a life-threatening acute asthma attack?','["PEFR <33% of best or predicted"]','A','Life-threatening asthma also includes SpO2 <92%, silent chest, cyanosis, poor respiratory effort, bradycardia, hypotension, exhaustion, confusion, or a normal/rising PaCO2 (indicating respiratory muscle fatigue).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','easy','flashcard','What spirometric criteria confirm an obstructive pattern reversible in asthma?','["FEV1/FVC <0.7 post-bronchodilator with reversibility ≥12% and ≥200 mL in FEV1"]','A','Reversibility testing uses 400 mcg salbutamol (or 2.5 mg nebulised); repeat spirometry at 15 minutes. Significant response supports asthma over COPD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','easy','flashcard','What is the Ghana STG first-line reliever for acute asthma?','["Salbutamol (SABA) — inhaled via MDI+spacer or nebulisation"]','A','Ghana STG 2017 recommends salbutamol 2.5–5 mg nebulised every 20 minutes for three doses in acute asthma, followed by reassessment. Ipratropium bromide may be added in severe attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','medium','flashcard','What are the GINA Step 3 treatment options for persistent asthma?','["Low-dose ICS + LABA, OR medium-dose ICS, OR low-dose ICS + LTRA"]','A','GINA Step 3 preferred controller is low-dose ICS/LABA combination. MART (Maintenance And Reliever Therapy) with budesonide/formoterol is an option at Steps 3–4. Step up if symptoms uncontrolled after 2–3 months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','medium','flashcard','When is IV magnesium sulphate indicated in acute severe asthma?','["Single dose 1.2–2 g IV over 20 minutes when not responding to initial bronchodilator and steroid therapy"]','A','IV MgSO4 causes smooth muscle relaxation via calcium antagonism. It is indicated in life-threatening asthma or acute severe asthma with poor response after 1 hour. Do not delay ICU if deteriorating.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','medium','flashcard','Which biologic is used for severe allergic asthma with high IgE levels?','["Omalizumab — anti-IgE monoclonal antibody, given SC every 2–4 weeks"]','A','Omalizumab binds free IgE, reducing mast cell activation. It is used at GINA Step 5 for patients ≥6 years with allergic asthma inadequately controlled on high-dose ICS/LABA. Serum total IgE must be 30–1500 IU/mL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','medium','flashcard','What is the MART regimen and at which GINA steps is it used?','["Maintenance And Reliever Therapy — budesonide/formoterol used as both daily controller and as-needed reliever at GINA Steps 3–4"]','A','MART uses the rapid onset of formoterol as a reliever while simultaneously increasing ICS dose during attacks. It reduces severe exacerbations compared to fixed-dose regimens.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','medium','flashcard','Which biologic targets IL-5 for severe eosinophilic asthma?','["Mepolizumab (anti-IL-5 monoclonal antibody), given SC monthly"]','A','Mepolizumab reduces blood and sputum eosinophils. It is indicated at GINA Step 5 for patients with eosinophilic asthma (blood eosinophils ≥300 cells/µL). Benralizumab (anti-IL-5Rα) is an alternative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','hard','flashcard','A patient with acute severe asthma has a normal PaCO2 of 5.5 kPa on ABG. Why is this alarming?','["Normal PaCO2 in acute severe asthma indicates exhaustion and impending respiratory failure — hyperventilation should normally reduce PaCO2 well below normal"]','A','In acute severe asthma, tachypnoea should produce a low PaCO2 (respiratory alkalosis). A normal or rising PaCO2 means the patient can no longer maintain hyperventilation — intubation may be imminent. This is a status asthmaticus red flag.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Asthma — Diagnosis & Management','hard','flashcard','How does the GINA LAMA add-on role differ between asthma and COPD treatment strategies?','["In asthma, LAMA (e.g. tiotropium) is a Step 4–5 add-on to ICS/LABA, not first-line; in COPD, LAMA is first-line maintenance therapy"]','A','Tiotropium (Respimat) is licensed as add-on therapy for asthma in patients ≥6 years with uncontrolled symptoms on ICS/LABA. It reduces exacerbations and improves lung function but must not replace ICS in asthma.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','easy','flashcard','What spirometric criterion is required to diagnose COPD?','["Post-bronchodilator FEV1/FVC ratio <0.7"]','A','COPD is diagnosed on spirometry, not symptoms alone. The fixed ratio <0.7 is used by GOLD guidelines. Some guidelines prefer the lower limit of normal (LLN) to avoid over-diagnosis in the elderly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','easy','flashcard','What are the FEV1 % predicted thresholds for GOLD stages 1–4 of COPD?','["GOLD 1 ≥80%, GOLD 2 50–79%, GOLD 3 30–49%, GOLD 4 <30% — all with FEV1/FVC <0.7 post-BD"]','A','GOLD staging guides therapy escalation and prognosis. GOLD 3–4 patients are at highest risk of exacerbations, hospitalisations and death. The BODE index (BMI, Obstruction, Dyspnoea, Exercise) predicts mortality better than FEV1 alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','easy','flashcard','What is first-line maintenance pharmacotherapy for stable COPD without frequent exacerbations?','["Long-acting muscarinic antagonist (LAMA) such as tiotropium 18 mcg once daily"]','A','Tiotropium reduces exacerbation frequency, improves exercise tolerance and quality of life. LABA (e.g. salmeterol, formoterol) is an alternative. LAMA+LABA is superior to either alone for breathlessness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','medium','flashcard','What are the LTOT criteria in COPD?','["PaO2 ≤55 mmHg on air, OR PaO2 ≤59 mmHg with cor pulmonale, polycythaemia or nocturnal desaturation"]','A','LTOT must be used ≥15 hours/day to improve survival in COPD with chronic hypoxaemia. Measurements should be taken when stable (≥3 weeks after exacerbation) on two occasions 3 weeks apart.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','medium','flashcard','What is the genetic cause of early-onset panacinar emphysema in a young non-smoker?','["Alpha-1 antitrypsin deficiency — PiZZ phenotype, causing uninhibited neutrophil elastase-mediated alveolar destruction"]','A','AATD should be suspected in COPD patients <45 years, minimal smoking history, or lower-lobe predominant emphysema. Serum AAT level <11 µmol/L is diagnostic. Weekly IV AAT augmentation therapy is available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','medium','flashcard','What is the treatment for a COPD exacerbation requiring hospital admission?','["Nebulised SABA/SAMA, systemic corticosteroids (prednisolone 30 mg/day × 5 days), antibiotics if purulent sputum, controlled oxygen, NIV if pH <7.35"]','A','Prednisolone shortens recovery and reduces treatment failure. Antibiotics (amoxicillin, doxycycline or co-amoxiclav) are given for purulent sputum or CXR consolidation. Target SpO2 88–92% in COPD to avoid hypercapnic drive suppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','medium','flashcard','What is roflumilast and in which COPD phenotype is it used?','["Roflumilast is a PDE4 inhibitor used as add-on therapy in GOLD 3–4 COPD with chronic bronchitis phenotype and frequent exacerbations"]','A','Roflumilast reduces exacerbation frequency by ~17%. It is an oral tablet taken once daily. Key side effects include weight loss, diarrhoea, nausea and neuropsychiatric effects. It is not a bronchodilator.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','medium','flashcard','When is triple therapy (LAMA+LABA+ICS) indicated in COPD?','["In COPD patients with frequent exacerbations (≥2/year or ≥1 hospitalisation) despite LAMA+LABA, especially with blood eosinophils ≥300 cells/µL"]','A','The IMPACT trial showed triple therapy with fluticasone furoate/umeclidinium/vilanterol reduced exacerbations vs dual therapy. ICS increases pneumonia risk; benefit is greater with high eosinophil counts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','hard','flashcard','What does the BODE index measure and what does a high score indicate?','["BODE = BMI, airflow Obstruction (FEV1%), Dyspnoea (MRC scale), Exercise capacity (6MWT); score 7–10 = 80% 4-year mortality"]','A','BODE index predicts all-cause mortality better than FEV1 alone. Lung volume reduction surgery or transplant should be considered in BODE scores ≥7 with upper-lobe emphysema and low exercise capacity.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','COPD — Diagnosis & Management','hard','flashcard','Why must oxygen be given in a controlled manner (target SpO2 88–92%) during a COPD exacerbation?','["Chronic CO2 retainers may rely on hypoxic drive; high-flow O2 abolishes this drive, causes V/Q mismatch worsening, Haldane effect and CO2 retention, risking hypercapnic coma"]','A','The Haldane effect: haemoglobin loaded with O2 releases CO2 less readily, raising PaCO2. Use 24–28% Venturi mask. If pH <7.35 and PaCO2 rising despite optimised treatment, start NIV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','easy','flashcard','What does each component of the CURB-65 score represent?','["Confusion (AMT ≤8), Urea >7 mmol/L, Respiratory rate ≥30/min, Blood pressure systolic <90 or diastolic ≤60 mmHg, age ≥65 years"]','A','CURB-65 score 0–1: low severity, home treatment. Score 2: moderate, consider hospital. Score 3–5: severe, consider ICU. Each criterion scores 1 point.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','easy','flashcard','What is the most common causative organism in community-acquired pneumonia?','["Streptococcus pneumoniae (pneumococcus)"]','A','Strep pneumoniae causes typical CAP with acute onset, productive cough, pleuritic chest pain, and lobar consolidation on CXR. Blood cultures are positive in ~25% of bacteraemic cases. Penicillin remains first-line.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','easy','flashcard','What is the Ghana STG 2017 first-line antibiotic for non-severe CAP managed in the community?','["Amoxicillin 500 mg TDS for 5–7 days orally"]','A','Ghana STG recommends amoxicillin as first-line for non-severe CAP. If atypical infection is suspected (young patient, dry cough, no response), add azithromycin or switch to doxycycline.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','medium','flashcard','What clinical and laboratory features suggest Legionella pneumophila as the causative organism in CAP?','["Hyponatraemia, raised LFTs (hepatitis), lymphopenia, diarrhoea, confusion, high fever, failure to respond to beta-lactams; confirmed by urinary Legionella antigen test"]','A','Legionella urinary antigen detects serogroup 1 (80% of cases) with sensitivity ~74% and specificity ~99%. Treatment is fluoroquinolone (levofloxacin) or macrolide (azithromycin). Outbreaks linked to cooling towers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','medium','flashcard','Which serological finding is associated with Mycoplasma pneumoniae CAP?','["Cold agglutinins (IgM autoantibodies against red cell I antigen) — present in ~50% of Mycoplasma CAP cases"]','A','Mycoplasma presents as atypical CAP with gradual onset, dry cough, headache and malaise. CXR shows diffuse infiltrates. Treatment is macrolide (azithromycin) or doxycycline. Cold agglutinins can cause haemolytic anaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','medium','flashcard','What is the empiric antibiotic regimen for moderate-to-severe CAP requiring hospital admission?','["IV co-amoxiclav (or amoxicillin + clavulanate) plus IV clarithromycin (or azithromycin) to cover both typical and atypical organisms"]','A','BTS/NICE guidance recommends combination beta-lactam + macrolide for hospitalised CAP. In high-severity CAP (CURB-65 3–5), use IV co-amoxiclav 1.2 g TDS + clarithromycin 500 mg BD. Duration 5–7 days (switch to oral when tolerating).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','medium','flashcard','How long does CXR resolution of CAP typically take, and when should non-resolution prompt investigation?','["CXR takes 6 weeks to clear in most cases; non-resolution at 6 weeks warrants repeat imaging and investigation for underlying malignancy"]','A','Slow-resolving pneumonia (non-resolution at 3 weeks, incomplete clearing at 6 weeks) should raise suspicion for obstructing tumour, tuberculosis, or immunodeficiency. CT chest and bronchoscopy may be indicated.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','medium','flashcard','Who should receive the pneumococcal polysaccharide vaccine (PPV23)?','["Adults ≥65 years; those with chronic lung/heart/kidney/liver disease, diabetes, asplenia, immunodeficiency, or cochlear implants"]','A','PPV23 gives protection against 23 serotypes. Conjugate vaccine PCV13 is given to infants and immunocompromised adults. In asplenic patients, also give meningococcal, Hib and annual influenza vaccines.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','hard','flashcard','What CXR patterns help distinguish typical from atypical CAP?','["Typical (lobar or segmental consolidation with air bronchograms — Strep pneumoniae); atypical (bilateral patchy or interstitial infiltrates — Mycoplasma, Legionella, Chlamydia, viruses)"]','A','Radiological patterns overlap; CXR cannot reliably identify causative organism. However, lobar consolidation in a feverish patient with productive cough strongly suggests pneumococcal infection and guides early empiric therapy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Community-Acquired Pneumonia','hard','flashcard','How does PSI/PORT class compare to CURB-65 for CAP severity assessment?','["PSI/PORT has 5 classes based on 20 variables (more accurate but complex); CURB-65 has 5 simple variables — both validated but CURB-65 preferred in clinical practice for speed"]','A','PSI Class I–II = low risk (outpatient). Class III = intermediate. Class IV–V = high risk (inpatient/ICU). CURB-65 is simpler but less validated in elderly and immunocompromised populations.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','easy','flashcard','How is hospital-acquired pneumonia (HAP) defined?','["Pneumonia developing ≥48 hours after hospital admission, not incubating at time of admission"]','A','HAP is the most common healthcare-associated infection and second most common nosocomial infection. Mortality is high (20–50%). Organisms differ from CAP, with resistant gram-negatives and MRSA predominating.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','easy','flashcard','How is ventilator-associated pneumonia (VAP) defined?','["Pneumonia occurring ≥48–72 hours after endotracheal intubation and mechanical ventilation"]','A','VAP is subdivided into early-onset (<5 days, less resistant organisms) and late-onset (≥5 days, higher risk of MDR pathogens). Diagnosis requires clinical, radiological and microbiological criteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','easy','flashcard','Which lung lobe is most commonly affected in aspiration pneumonia and why?','["Right lower lobe — the right main bronchus is more vertical, wider and shorter, making aspiration more likely to reach the right lower lobe when upright or semi-recumbent"]','A','In supine patients, the posterior segments of upper lobes and superior segments of lower lobes are affected. Anaerobes from oral flora are key pathogens (Peptostreptococcus, Bacteroides, Fusobacterium). Treatment: co-amoxiclav or metronidazole + amoxicillin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','medium','flashcard','What are the key pathogens in late-onset HAP/VAP and the recommended empiric antibiotic regimen?','["MRSA, Pseudomonas aeruginosa, Klebsiella pneumoniae, Acinetobacter baumannii; empiric: piperacillin-tazobactam or meropenem ± vancomycin/linezolid for MRSA cover"]','A','Meropenem is preferred for ESBL-producing organisms. Vancomycin or linezolid should be added if MRSA risk is high (prior MRSA colonisation, recent antibiotics, ICU >5 days). De-escalate based on cultures within 48–72 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','medium','flashcard','What is Mendelson syndrome and how does it differ from aspiration pneumonia?','["Mendelson syndrome is chemical pneumonitis from aspiration of gastric acid (pH <2.5) causing acute inflammation WITHOUT infection; aspiration pneumonia involves bacterial infection from aspirated oropharyngeal/gastric contents"]','A','Chemical pneumonitis presents acutely with bronchospasm, hypoxia and bilateral infiltrates within hours of aspiration. It is self-limiting; antibiotics are not needed unless secondary bacterial infection develops (>48–72 hours, fever returning, new infiltrates).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','medium','flashcard','What are the key components of the VAP prevention bundle?','["Head-of-bed elevation 30–45°, daily sedation holds, oral decontamination with chlorhexidine 0.12%, subglottic secretion drainage, stress ulcer and DVT prophylaxis"]','A','Each element of the VAP bundle independently reduces VAP incidence. Chlorhexidine oral care reduces VAP by ~30%. Avoiding unnecessary reintubation and minimising ventilator duration are also critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','medium','flashcard','What are the risk factors for aspiration pneumonia in hospitalised patients?','["Depressed consciousness (stroke, seizures, anaesthesia, sedation), dysphagia, NG tube feeding, supine position, poor oral hygiene, gastroparesis"]','A','Stroke is the single biggest risk factor for aspiration pneumonia. All stroke patients should undergo bedside swallow assessment before oral intake. Nasogastric feeding also increases aspiration risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','medium','flashcard','What is the preferred antibiotic for aspiration pneumonia involving anaerobic organisms?','["Co-amoxiclav (amoxicillin-clavulanate) as first-line; alternatively, metronidazole combined with a penicillin or cephalosporin"]','A','Co-amoxiclav covers oral anaerobes, streptococci and gram-negatives. In penicillin-allergic patients, use clindamycin (good anaerobic cover) or moxifloxacin. Duration typically 5–7 days for uncomplicated cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','hard','flashcard','Why is Acinetobacter baumannii particularly problematic in HAP/VAP and what treatment options exist?','["Acinetobacter is intrinsically resistant and rapidly acquires multi-drug resistance; treatment options for XDR strains are limited to colistin (polymyxin E) ± rifampicin or tigecycline"]','A','Colistin (polymyxin E) is nephrotoxic and neurotoxic but is a last resort for carbapenem-resistant Acinetobacter baumannii (CRAB). Sulbactam combinations and cefiderocol are emerging options. Infection control is paramount.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Hospital-Acquired & Aspiration Pneumonia','hard','flashcard','What distinguishes early-onset from late-onset HAP in terms of likely pathogens and treatment strategy?','["Early-onset HAP (<5 days): Strep pneumoniae, H. influenzae, MSSA — treat as CAP; late-onset HAP (≥5 days): MDR organisms (Pseudomonas, MRSA, ESBL Klebsiella, Acinetobacter) — broad-spectrum empiric therapy required"]','A','The transition from early to late-onset HAP reflects colonisation pressure in the hospital environment. Early-onset HAP can often be treated with narrow-spectrum antibiotics, avoiding toxicity and resistance selection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','easy','flashcard','What Mantoux (tuberculin skin test) induration size indicates a positive result in an immunocompetent patient?','["≥10 mm induration at 48–72 hours is positive in immunocompetent individuals; ≥5 mm is positive in HIV-positive patients or those on immunosuppressants"]','A','BCG vaccination causes false positives with Mantoux. IGRA tests (QuantiFERON-TB Gold, T-SPOT.TB) are not affected by BCG and are preferred for LTBI diagnosis in BCG-vaccinated populations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','easy','flashcard','What is the standard sputum collection protocol for AFB smear microscopy in suspected pulmonary TB?','["Three early morning sputum specimens (spot-early morning-spot) for ZN staining; at least 2 AFB-positive smears confirm pulmonary TB"]','A','Early morning specimens have the highest mycobacterial load. ZN staining detects 5,000–10,000 bacilli/mL (low sensitivity ~50–60%). Culture on Lowenstein-Jensen medium is more sensitive but takes 2–8 weeks. GeneXpert is faster.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','easy','flashcard','What are the classic CXR findings in post-primary (reactivation) pulmonary tuberculosis?','["Upper lobe cavitation, fibrosis, consolidation, calcification; miliary pattern (diffuse 1–3 mm nodules throughout both lungs) in miliary TB"]','A','Upper lobe predominance reflects high oxygen tension favouring mycobacterial growth. In HIV-positive patients with low CD4, TB may present with lower/middle lobe infiltrates or atypical patterns. Miliary TB suggests haematogenous dissemination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','medium','flashcard','How does GeneXpert MTB/RIF improve TB diagnosis compared to smear microscopy?','["GeneXpert detects MTB DNA and rifampicin resistance (RpoB gene) in 2 hours with sensitivity ~88% in smear-positive, ~67% in smear-negative TB; not affected by operator skill"]','A','GeneXpert (Xpert MTB/RIF Ultra) is WHO-recommended as the initial diagnostic test for TB in most settings. It can be used on sputum, CSF, lymph node aspirates and other specimens. It detects rifampicin resistance as a proxy for MDR-TB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','medium','flashcard','Why is IGRA preferred over Mantoux in BCG-vaccinated individuals for LTBI screening?','["IGRA measures IFN-γ release by sensitised T-cells to TB-specific antigens (ESAT-6, CFP-10) absent from BCG; BCG vaccination does not cause false-positive IGRA results"]','A','QuantiFERON-TB Gold Plus requires a single blood draw. T-SPOT.TB requires PBMC isolation. Both have higher specificity than Mantoux in BCG-vaccinated populations. Neither can distinguish active from latent TB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','medium','flashcard','What are the common extrapulmonary sites of tuberculosis?','["Lymph nodes (most common extrapulmonary), pleura, spine (Pott''s disease), genitourinary tract, CNS (tuberculous meningitis), pericardium, peritoneum, adrenal glands"]','A','In HIV-positive patients, extrapulmonary TB is more common. TB lymphadenitis presents as painless cervical lymphadenopathy with matting and possible caseation/fistula. Spinal TB causes vertebral body destruction and potential cord compression (Pott''s paraplegia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','medium','flashcard','What are the classical symptoms of pulmonary tuberculosis?','["Chronic productive cough >3 weeks, haemoptysis, fever, night sweats, weight loss, fatigue, anorexia"]','A','TB symptoms are constitutional and respiratory. Night sweats and weight loss reflect cytokine-mediated systemic inflammation. Haemoptysis may indicate cavitary disease or Rasmussen aneurysm (pulmonary artery erosion into a cavity).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','medium','flashcard','How does HIV-TB coinfection affect the diagnostic approach to tuberculosis?','["HIV-TB patients have higher rates of smear-negative, extrapulmonary and disseminated TB; lower CD4 counts give atypical CXR; GeneXpert and culture essential; urine lipoarabinomannan (LAM) useful if CD4 <100"]','A','WHO recommends urine LF-LAM (lateral flow lipoarabinomannan assay) in HIV-positive inpatients with CD4 <100 cells/µL or seriously ill. Sensitivity in this group is ~42%, specificity ~91%. It guides empiric TB treatment decisions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','hard','flashcard','What CSF findings are typical of tuberculous meningitis?','["CSF: lymphocytic pleocytosis (100–500 cells/µL), elevated protein (>1 g/L), low glucose (<50% plasma), AFB smear positive in <40%; ZN of pellicle/fibrin web improves yield; GeneXpert CSF recommended"]','A','TB meningitis has a subacute onset (days–weeks) unlike bacterial meningitis. Cranial nerve palsies (III, VI, VII) and hydrocephalus are complications. Dexamethasone 0.4 mg/kg/day reduces mortality. Start empiric treatment before culture results if clinically suspected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Diagnosis','hard','flashcard','What distinguishes MDR-TB from XDR-TB and pre-XDR-TB?','["MDR-TB: resistant to rifampicin + isoniazid; pre-XDR-TB: MDR-TB + resistance to any fluoroquinolone; XDR-TB (new 2021 WHO definition): MDR/RR-TB + resistance to any fluoroquinolone + at least one of bedaquiline or linezolid"]','A','The 2021 WHO XDR-TB definition replaced the older definition requiring resistance to injectable aminoglycosides. XDR-TB has a very poor prognosis. New drugs bedaquiline, pretomanid and linezolid (BPaL regimen) have improved outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','easy','flashcard','What is the standard first-line TB treatment regimen for drug-sensitive pulmonary TB?','["2RHZE/4RH — rifampicin, isoniazid, pyrazinamide, ethambutol for 2 months (intensive phase), then rifampicin + isoniazid for 4 months (continuation phase)"]','A','All four drugs are given daily. Total treatment duration is 6 months. For TB meningitis or bone/joint TB, the continuation phase is extended to 10 months (total 12 months). DOT (directly observed therapy) is standard of care.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','easy','flashcard','What side effect of isoniazid can be prevented with pyridoxine (vitamin B6) supplementation?','["Peripheral neuropathy — isoniazid inhibits pyridoxine metabolism; pyridoxine 10–25 mg/day prevents this in at-risk patients (malnutrition, pregnancy, diabetes, alcohol excess, HIV)"]','A','Isoniazid also causes hepatotoxicity and rare drug-induced lupus. Slow acetylators (common in Africans) have higher isoniazid levels and greater neuropathy risk. Pyridoxine is routinely given with isoniazid in Ghana.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','easy','flashcard','Why does rifampicin cause orange/red discolouration of body fluids?','["Rifampicin and its metabolites are red-orange in colour and are excreted in urine, tears, sweat and saliva — a harmless but important side effect to warn patients about"]','A','Rifampicin is a potent CYP450 inducer (CYP3A4, CYP2C9, CYP2C19) — it accelerates metabolism of warfarin, oral contraceptives, antiretrovirals, steroids and many other drugs. Drug interactions must always be reviewed at TB treatment initiation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','medium','flashcard','What is the key ocular side effect of ethambutol and how should it be monitored?','["Optic neuritis — presents as reduced visual acuity, colour vision loss (red-green) and central scotoma; monitor with monthly Snellen chart and Ishihara colour plates; stop immediately if detected"]','A','Ethambutol optic neuritis is dose-dependent and usually reversible if detected early. Baseline visual acuity should be documented before starting treatment. Ethambutol should be avoided in children too young for reliable visual testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','medium','flashcard','What metabolic complication is associated with pyrazinamide use in TB treatment?','["Hyperuricaemia — pyrazinamide inhibits renal tubular uric acid secretion, precipitating gout in susceptible patients"]','A','Pyrazinamide-induced gout can be managed with allopurinol if TB treatment must continue. Pyrazinamide also causes hepatotoxicity (monitor LFTs monthly for first 2 months) and rash. It is especially active against intracellular bacilli in macrophages.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','medium','flashcard','What is the recommended management when TB and HIV coinfection are diagnosed simultaneously?','["Start TB treatment first; initiate ART within 2–8 weeks (earlier for CD4 <50 cells/µL — start within 2 weeks of TB treatment)"]','A','Delaying ART risks AIDS progression and death; starting too early risks immune reconstitution inflammatory syndrome (IRIS). The CAMELIA and STRIDE trials showed early ART (2 weeks) reduces mortality in patients with CD4 <50. Efavirenz-based ART preferred with rifampicin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','medium','flashcard','What are the two standard regimens for treating latent TB infection (LTBI)?','["6H (isoniazid alone × 6 months) or 3RH (rifampicin + isoniazid × 3 months); 3HP (weekly rifapentine + isoniazid × 3 months) is an alternative"]','A','LTBI treatment reduces TB reactivation risk by ~60–90%. Indications include recent TB contact, HIV-positive status, immunosuppressant use, IGRA/Mantoux positive with no active TB. Liver function must be monitored in older patients and alcohol users.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','medium','flashcard','What is directly observed therapy (DOT) in TB management and why is it used?','["DOT requires a healthcare worker to watch the patient swallow every TB medication dose; it ensures adherence, prevents resistance development and is WHO-recommended standard of care"]','A','Non-adherence is the leading cause of treatment failure and MDR-TB. Community-based DOT (home or community health worker) improves outcomes versus clinic-based DOT. Video-observed therapy (VOT) is an emerging alternative in resource-limited settings.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','hard','flashcard','What is the BPaL regimen for XDR-TB and what trial validated it?','["BPaL = Bedaquiline + Pretomanid + Linezolid × 6 months; validated in the ZeNix and TB-PRACTECAL trials with 89% culture conversion at 6 months"]','A','Bedaquiline inhibits mycobacterial ATP synthase. Pretomanid is a nitroimidazole prodrug (reactive nitrogen species). Linezolid inhibits 50S ribosomal protein synthesis. Key toxicities: bedaquiline QTc prolongation; linezolid peripheral neuropathy and myelosuppression.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Tuberculosis — Treatment','hard','flashcard','Why is rifampicin a critical drug interaction concern in HIV-TB coinfection, and how is it managed?','["Rifampicin strongly induces CYP3A4, markedly reducing levels of most HIV protease inhibitors and some NNRTIs; efavirenz levels fall by ~25% but remain therapeutic; raltegravir or dolutegravir can also be used with dose adjustment"]','A','Rifampicin reduces lopinavir/ritonavir levels by >75% (clinically ineffective). Efavirenz dose of 600 mg/day is standard with rifampicin. Dolutegravir 50 mg BD (doubled dose) is an effective alternative. Avoid rifampicin with most boosted PI regimens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','easy','flashcard','What are Light''s criteria for distinguishing exudative from transudative pleural effusions?','["Exudate if ANY of: pleural fluid LDH/serum LDH >0.6; pleural fluid protein/serum protein >0.5; pleural fluid LDH >2/3 upper limit of normal serum LDH"]','A','Light''s criteria sensitivity for exudate is ~98%, specificity ~83%. About 20–30% of transudates (especially diuretic-treated heart failure) are misclassified as exudates by Light''s criteria. Serum-effusion albumin gradient >12 g/L suggests transudate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','easy','flashcard','What are the main causes of transudative pleural effusions?','["Congestive cardiac failure (most common), hepatic cirrhosis with ascites (hepatic hydrothorax), nephrotic syndrome, hypoalbuminaemia, hypothyroidism, peritoneal dialysis"]','A','Transudates result from increased hydrostatic pressure or decreased oncotic pressure. CCF causes bilateral effusions (right > left). Pleural fluid protein <25 g/L and LDH <200 IU/L suggest transudate. Furosemide diuresis is the primary treatment in CCF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','easy','flashcard','What pleural fluid criteria indicate that a parapneumonic effusion has progressed to empyema requiring chest drain?','["pH <7.2, glucose <2.2 mmol/L, frank pus, positive Gram stain or culture — any of these mandates chest drain drainage"]','A','Empyema (pus in the pleural space) will not resolve with antibiotics alone. Large-bore chest drain (20–28 Fr) is inserted in the 5th intercostal space, mid-axillary line (safe triangle). Intrapleural fibrinolytics (alteplase + DNase) used for loculated empyema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','medium','flashcard','What is the maximum volume of pleural fluid that should be aspirated in a single therapeutic thoracocentesis and why?','["Maximum 1.5 litres in a single sitting to prevent re-expansion pulmonary oedema"]','A','Re-expansion pulmonary oedema occurs when a chronically collapsed lung re-expands rapidly — protein-rich interstitial oedema fills the alveoli. It is rare but potentially fatal. Stop aspiration if the patient develops chest tightness, cough or breathlessness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','medium','flashcard','What is Meigs syndrome and what is its classic triad?','["Meigs syndrome: benign ovarian fibroma (or fibrothecoma) + right-sided pleural effusion + ascites — all resolve after tumour removal"]','A','Meigs syndrome is important to distinguish from malignant ascites and pleural effusion. CA-125 may be elevated, mimicking ovarian malignancy. Resolution of effusion and ascites after tumour resection confirms the diagnosis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','medium','flashcard','How is malignant pleural effusion managed?','["Repeated therapeutic thoracocentesis, indwelling pleural catheter (IPC) for palliation, or talc pleurodesis (chemical) to obliterate pleural space and prevent re-accumulation"]','A','Malignant effusions recur rapidly. IPC allows outpatient drainage with good palliation. Talc pleurodesis (talc slurry via chest drain or talc poudrage at VATS) is effective if the lung can fully re-expand. Lung cancer, breast cancer and mesothelioma are the most common causes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','medium','flashcard','What pleural fluid findings suggest tuberculous pleuritis?','["Exudate with lymphocytic predominance (>80% lymphocytes), elevated ADA (adenosine deaminase >40 IU/L), high protein, low glucose; AFB smear rarely positive; pleural biopsy shows caseating granulomas"]','A','ADA >40 IU/L has sensitivity ~92% and specificity ~90% for TB pleuritis in high-prevalence settings. Pleural fluid culture for MTB takes 6–8 weeks. If AFB smear negative, Abrams needle biopsy or VATS biopsy increases diagnostic yield.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','medium','flashcard','What are the causes of a haemothorax?','["Trauma (rib fractures, penetrating chest injury) — most common; spontaneous haemothorax from malignancy, aortic aneurysm rupture, coagulopathy, anticoagulation, pulmonary embolism, AVM"]','A','Haemothorax is diagnosed when pleural fluid haematocrit is >50% of blood haematocrit. Management: drain with large-bore tube. Massive haemothorax (>1500 mL) or ongoing bleeding (>200 mL/hour) requires thoracotomy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','hard','flashcard','Why might Light''s criteria misclassify a treated CCF effusion as an exudate, and how is this corrected?','["Diuretics concentrate pleural proteins and LDH, pushing values into exudate range despite a haemodynamic (transudative) cause; the serum-effusion albumin gradient >12 g/L or NT-proBNP >1500 pg/mL suggests cardiac transudate"]','A','The serum-effusion albumin gradient corrects for diuretic-induced protein concentration. NT-proBNP in pleural fluid mirrors serum levels and is highly sensitive for CCF-related effusions. Always correlate pleural biochemistry with clinical context.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pleural Effusion & Empyema','hard','flashcard','What is the role of intrapleural alteplase and DNase in empyema management?','["Intrapleural alteplase 10 mg + DNase 5 mg (given alternately twice daily for 3 days) breaks down fibrin loculations and reduces viscosity of pus, improving drainage — validated in the MIST2 trial"]','A','MIST2 showed combination alteplase+DNase significantly reduced surgical referral compared to placebo or either agent alone. Neither agent alone was effective. Contraindicated if pleural-bronchial communication (risk of systemic thrombolysis).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','easy','flashcard','What are the immediate clinical signs of a tension pneumothorax?','["Tracheal deviation away from the side of the pneumothorax, absent breath sounds on the affected side, hypotension, raised JVP, tachycardia and respiratory distress"]','A','Tension pneumothorax is a clinical emergency — do NOT wait for CXR. Perform immediate needle decompression: 14–16G cannula, 2nd intercostal space, mid-clavicular line. Then insert definitive chest drain at 5th ICS, mid-axillary line (safe triangle).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','easy','flashcard','What is the difference between primary and secondary spontaneous pneumothorax?','["Primary spontaneous pneumothorax (PSP) occurs in young, tall, lean patients with no underlying lung disease (subpleural blebs); secondary spontaneous pneumothorax (SSP) complicates underlying lung disease (COPD, asthma, CF, TB, Marfan syndrome)"]','A','PSP is more common in males aged 15–35. SSP is more dangerous because the patient has reduced respiratory reserve. Both have higher recurrence rates than traumatic pneumothorax (PSP recurrence ~30% at 5 years).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','easy','flashcard','At what spontaneous resorption rate does air resolve from an untreated pneumothorax?','["Air resorbs at approximately 1.25% of the pneumothorax volume per day without intervention"]','A','High-flow oxygen (10–15 L/min via non-rebreather mask) increases nitrogen washout and quadruples resorption rate. This is useful for small PSP managed conservatively. The patient must not smoke (delays resolution).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','medium','flashcard','According to BTS 2010 guidelines, how should a symptomatic PSP with pneumothorax rim >2 cm be managed?','["Aspiration (16G cannula, 2nd ICS MCL, aspirate up to 2.5 L); if unsuccessful, insert small-bore chest drain (8–14 Fr Seldinger); if fails, refer for thoracic opinion"]','A','BTS guidelines recommend needle aspiration as the first intervention for symptomatic PSP >2 cm. Success rate ~50–70%. If lung fails to re-expand or patient deteriorates, chest drain insertion is required. Water-seal drain; do not apply suction initially.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','medium','flashcard','How is secondary spontaneous pneumothorax managed differently from primary?','["SSP >1 cm or any SSP in a breathless patient: immediate chest drain (do not aspirate first); all SSP patients should be admitted due to underlying lung disease reducing reserve"]','A','SSP patients cannot tolerate reduced lung function. Aspiration alone is inadequate for SSP >2 cm. Chest drain in 5th ICS, mid-axillary line. Consider early VATS pleurodesis if first SSP because of high mortality risk with recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','medium','flashcard','What is the genetic connective tissue disorder most associated with recurrent pneumothorax?','["Marfan syndrome — FBN1 gene mutation causing tall stature, arachnodactyly, lens dislocation, aortic root dilatation and subpleural blebs predisposing to PSP"]','A','Other associations: Ehlers-Danlos syndrome (EDS), Birt-Hogg-Dubé syndrome (FLCN mutation — also causes renal tumours and fibrofolliculomas), lymphangioleiomyomatosis (LAM, TSC2/TCS1 — women of reproductive age). All warrant pleurodesis for recurrence.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','medium','flashcard','What are the indications for surgical management (VATS) in pneumothorax?','["Second ipsilateral pneumothorax, first contralateral pneumothorax, bilateral simultaneous pneumothorax, persistent air leak >5–7 days, failure of chest drain, high-risk occupation (diver, pilot), patient preference for prevention"]','A','VATS pleurodesis with pleural abrasion or pleurectomy has recurrence rate <5%. Chemical pleurodesis (talc insufflation at VATS) is equally effective. Patients must be warned to avoid diving permanently after any pneumothorax.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','medium','flashcard','How should a chest drain be inserted safely to avoid neurovascular bundle injury?','["Insert over the upper border of the lower rib in the 5th ICS, mid-axillary line (triangle of safety: lateral border of pectoralis major, anterior border of latissimus dorsi, above the nipple line)"]','A','Neurovascular bundles (intercostal nerve, artery, vein) run in the subcostal groove on the lower border of each rib. Inserting over the upper border avoids these structures. Always use blunt dissection and guided technique (Seldinger for small-bore drains).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','hard','flashcard','How does a pneumothorax produce haemodynamic compromise in tension physiology?','["Air enters pleural space but cannot exit; intrapleural pressure rises above atmospheric, compressing ipsilateral lung, shifting mediastinum contralaterally, kinking the SVC/IVC, reducing venous return and cardiac output"]','A','Obstructive shock results from reduced preload. The mediastinal shift also compresses the contralateral lung. Death can occur within minutes. PEA cardiac arrest from tension pneumothorax is reversible with immediate needle decompression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pneumothorax','hard','flashcard','What is catamenial pneumothorax and how does it present?','["Catamenial pneumothorax occurs within 24–72 hours of menstruation in women with thoracic endometriosis; right-sided (90%), recurrent; treated with hormonal suppression (GnRH agonists) plus VATS with diaphragmatic resection"]','A','Pathogenesis: diaphragmatic defects allow passage of peritoneal air during menstruation; alternatively, endometrial implants on the pleura bleed and degenerate, releasing air. Often misdiagnosed as primary spontaneous pneumothorax.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','easy','flashcard','What are the components of the Wells score for pulmonary embolism?','["Clinical signs of DVT (+3), PE most likely diagnosis (+3), HR >100 (+1.5), immobilisation/surgery last 4 weeks (+1.5), prior DVT/PE (+1.5), haemoptysis (+1), malignancy (+1); ≤4 = low probability; >4 = high probability"]','A','Wells score ≤4 with negative D-dimer effectively excludes PE (NPV ~99%). Wells >4 requires imaging (CTPA). PERC rule can be used to rule out PE without D-dimer if all 8 criteria met in low pre-test probability patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','easy','flashcard','What is the gold standard investigation for diagnosing pulmonary embolism?','["CT pulmonary angiography (CTPA) — sensitivity ~96%, specificity ~98%; demonstrates filling defects in pulmonary arteries"]','A','CTPA also identifies alternative diagnoses (pneumonia, pneumothorax, aortic dissection). V/Q scan is used when CTPA is contraindicated (renal failure, contrast allergy, pregnancy). Bilateral proximal DVT compression USS can support PE diagnosis if CTPA unavailable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','easy','flashcard','What are the components of Virchow''s triad for venous thromboembolism?','["Stasis (immobility, CCF, pregnancy), endothelial injury (surgery, trauma, central venous catheters), hypercoagulability (malignancy, thrombophilia, OCP, Factor V Leiden, antiphospholipid syndrome)"]','A','Virchow''s triad explains the pathogenesis of DVT and PE. All hospitalised patients should be risk-assessed for VTE. Cancer is the strongest acquired risk factor — accounts for ~20% of all VTE. Thrombophilia screen after unprovoked PE/DVT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','medium','flashcard','What is the treatment for massive (high-risk) pulmonary embolism with haemodynamic compromise?','["Systemic thrombolysis: IV alteplase 100 mg over 2 hours (or 0.6 mg/kg over 15 min in cardiac arrest); surgical embolectomy or catheter-directed thrombolysis if thrombolysis contraindicated"]','A','Massive PE: SBP <90 mmHg for >15 min or requiring vasopressors. Anticoagulate with unfractionated heparin (not LMWH) while considering thrombolysis. Key contraindications to thrombolysis: recent surgery (<10 days), stroke <3 months, active bleeding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','medium','flashcard','What ECG finding is classically described in pulmonary embolism, and how sensitive is it?','["S1Q3T3 pattern (S wave in lead I, Q wave and T-wave inversion in lead III) — present in only ~12–20% of PE cases; sinus tachycardia is the most common ECG finding"]','A','Right heart strain pattern (S1Q3T3, right bundle branch block, right axis deviation, T-wave inversions V1–V4) reflects acute right ventricular pressure overload. ECG alone cannot diagnose or exclude PE but supports clinical suspicion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','medium','flashcard','What is the McConnell sign on echocardiography in acute pulmonary embolism?','["McConnell sign: right ventricular free wall hypokinesis with sparing of the RV apex — highly specific (~94%) for acute PE but low sensitivity (~77%)"]','A','The spared RV apex contracts because it is tethered to the interventricular septum and LV. Echo also shows RV dilatation, D-shape of the LV (septal shift), tricuspid regurgitation and elevated PA pressures. Useful for bedside assessment in unstable patients.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','medium','flashcard','What is the recommended duration of anticoagulation after a first unprovoked PE?','["At least 3 months; then reassess — most guidelines recommend extending to 6 months or indefinitely in unprovoked PE if bleeding risk is acceptable"]','A','Provoked PE (surgery, long-haul flight): 3 months then stop. Unprovoked PE: at least 6 months; consider indefinite if low bleeding risk (DOAC apixaban 2.5 mg BD or rivaroxaban 10 mg OD for extended treatment). Cancer-associated VTE: LMWH or edoxaban.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','medium','flashcard','What are the indications for an IVC filter in pulmonary embolism management?','["Absolute contraindication to anticoagulation (active major bleeding, recent intracranial bleed), recurrent PE despite adequate anticoagulation, or as adjunct to thrombolysis/embolectomy in massive PE"]','A','IVC filters reduce the risk of PE from leg DVT but do NOT treat existing thrombus and increase long-term DVT risk. Retrievable filters should be removed once anticoagulation is safe to restart. They are not used routinely in anticoagulated patients.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','hard','flashcard','What are the HESTIA criteria used for in pulmonary embolism management?','["HESTIA criteria identify low-risk PE patients suitable for outpatient treatment; if all 11 criteria are absent (haemodynamic instability, need for supplemental O2, severe pain, high bleeding risk, renal/hepatic failure, pregnancy, etc.), outpatient DOAC treatment is safe"]','A','The HESTIA rule is simple and validated for outpatient PE management. DOACs (rivaroxaban or apixaban) are approved for outpatient PE. Early discharge reduces hospital-acquired complications and costs. sPESI score 0 is an alternative selection tool.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Pulmonary Embolism','hard','flashcard','What is chronic thromboembolic pulmonary hypertension (CTEPH) and how is it treated?','["CTEPH: organised thrombus does not resolve, causing fixed pulmonary vascular obstruction and progressive PH (mPAP >25 mmHg) ≥3 months after PE; treated with pulmonary endarterectomy (PEA) if operable, or riociguat + balloon pulmonary angioplasty if inoperable"]','A','CTEPH occurs in ~4% of patients after PE. Lifelong anticoagulation is essential. Riociguat is the only approved medical therapy for inoperable CTEPH. PEA is curative in operable cases with excellent long-term outcomes.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','easy','flashcard','What are the two main histological categories of lung cancer and their relative frequencies?','["Non-small cell lung cancer (NSCLC) ~85%: adenocarcinoma ~40%, squamous cell carcinoma ~30%, large cell carcinoma ~15%; Small cell lung cancer (SCLC) ~15%"]','A','Adenocarcinoma is the most common type overall and most common in non-smokers and women. Squamous cell carcinoma is central, strongly linked to smoking. SCLC grows rapidly, metastasises early and is initially chemosensitive but rapidly develops resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','easy','flashcard','What is the paraneoplastic syndrome associated with squamous cell carcinoma of the lung?','["Hypercalcaemia of malignancy — caused by tumour secretion of PTHrP (parathyroid hormone-related protein), not bone metastases"]','A','PTHrP binds PTH receptors causing bone resorption, renal calcium reabsorption and phosphate wasting. Treat with IV fluids, bisphosphonates (zoledronic acid) and denosumab. Squamous cell carcinoma can also cause finger clubbing and hypertrophic pulmonary osteoarthropathy (HPOA).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','easy','flashcard','What targeted therapy is used for NSCLC with an EGFR-activating mutation?','["Osimertinib (third-generation EGFR TKI) — first-line for EGFR exon 19 deletion or exon 21 L858R mutation; crosses blood-brain barrier, overcoming T790M resistance"]','A','EGFR mutations are found in ~10–15% of Western NSCLC patients and ~30–40% in East Asians. Osimertinib showed PFS benefit over earlier generation TKIs in the FLAURA trial. Brain metastases respond well to osimertinib.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','medium','flashcard','What paraneoplastic syndromes are specifically associated with small cell lung cancer (SCLC)?','["SIADH (hyponatraemia from ectopic ADH), Lambert-Eaton myasthenic syndrome (VGCC antibodies causing proximal weakness that improves with repeated muscle use, unlike MG), Cushing syndrome (ectopic ACTH)"]','A','Lambert-Eaton: voltage-gated calcium channel (VGCC) antibodies at pre-synaptic nerve terminal reduce ACh release. Reflexes improve with repeated stimulation (EMG shows incremental response). Treat the underlying SCLC and consider amifampridine for Lambert-Eaton.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','medium','flashcard','What is a Pancoast tumour and what syndrome does it cause?','["Pancoast tumour (superior sulcus tumour) is an NSCLC at the apex of the lung invading the brachial plexus (C8-T1), subclavian vessels and sympathetic chain, causing Horner syndrome (ptosis, miosis, anhidrosis, enophthalmos) and ipsilateral arm/shoulder pain"]','A','Pancoast tumours are usually squamous cell or adenocarcinoma. They may be resectable if no mediastinal involvement. Treatment: concurrent chemoradiotherapy (cisplatin + etoposide + radiotherapy) then surgical resection if response is adequate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','medium','flashcard','When is pembrolizumab appropriate as first-line treatment in NSCLC?','["Pembrolizumab monotherapy is first-line in advanced NSCLC if PD-L1 TPS ≥50% and no EGFR/ALK/ROS1 driver mutations; PD-L1 1–49%: pembrolizumab + chemotherapy"]','A','The KEYNOTE-024 trial showed pembrolizumab superior to chemotherapy in PD-L1 ≥50% NSCLC. Immune-related adverse events (irAEs) include pneumonitis, colitis, hepatitis, thyroiditis and adrenal insufficiency. Treat irAEs with high-dose steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','medium','flashcard','What targeted therapy is used for NSCLC with ALK gene rearrangement?','["Alectinib (second-generation ALK inhibitor) — first-line preferred over crizotinib; superior CNS penetration and efficacy in ALK-rearranged NSCLC"]','A','ALK rearrangement occurs in ~5% of NSCLC, typically younger patients, never/light smokers, adenocarcinoma histology. ALEX trial: alectinib significantly superior to crizotinib for PFS and CNS response. Lorlatinib used for resistance to alectinib.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','medium','flashcard','What is the standard chemotherapy regimen for extensive-stage SCLC?','["Cisplatin + etoposide (PE) × 4–6 cycles; atezolizumab (PD-L1 inhibitor) added to chemotherapy in first-line extensive SCLC based on IMpower133 trial"]','A','SCLC responds well to initial chemotherapy but almost universally relapses within 6–12 months (acquired resistance). Prophylactic cranial irradiation (PCI) in limited-stage SCLC reduces brain metastasis risk and improves survival.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','hard','flashcard','What is superior vena cava (SVC) obstruction syndrome and how is it managed?','["SVC obstruction from external compression (lung cancer, lymphoma) or thrombosis causes facial oedema, arm oedema, dilated neck/chest veins, headache, dyspnoea; urgent management: dexamethasone 8 mg TDS + SVC stenting + radiotherapy/chemotherapy for underlying malignancy"]','A','SCLC and NHL respond rapidly to systemic treatment. NSCLC often requires SVC stenting for faster relief. Do not delay stenting for histological diagnosis if the patient is critically compromised. SVC stenting relieves symptoms within 24–48 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Lung Cancer — Clinical Management','hard','flashcard','What is hypertrophic pulmonary osteoarthropathy (HPOA) and which lung cancer type most commonly causes it?','["HPOA: painful periosteal new bone formation (long bones), joint effusions and digital clubbing; most commonly caused by adenocarcinoma and squamous cell carcinoma of the lung; periosteal reaction visible on plain X-ray"]','A','HPOA is caused by IGF-1 and PDGF release from tumour or megakaryocytes traversing pulmonary circulation. Periosteal reaction causes pain and tenderness of the distal long bones. Treatment of the underlying cancer can reverse HPOA. Also seen with mesothelioma.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','easy','flashcard','What are the ABG criteria for Type 1 and Type 2 respiratory failure?','["Type 1 (hypoxaemic): PaO2 <8 kPa (<60 mmHg) with normal or low PaCO2; Type 2 (hypercapnic): PaO2 <8 kPa AND PaCO2 >6 kPa (>45 mmHg)"]','A','Type 1 RF: V/Q mismatch, shunt, diffusion impairment (pneumonia, pulmonary oedema, PE, ARDS). Type 2 RF: alveolar hypoventilation — COPD, neuromuscular disease, obesity hypoventilation, sedation. Type 2 RF always has a compensatory or primary metabolic component.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','easy','flashcard','What are the Berlin criteria for diagnosing ARDS?','["Acute onset within 1 week of known insult; bilateral infiltrates on CXR/CT not fully explained by effusion/collapse/nodules; PaO2/FiO2 ratio ≤300 mmHg on CPAP/PEEP ≥5 cmH2O; not fully explained by cardiac failure or fluid overload"]','A','ARDS severity: mild PaO2/FiO2 200–300 (replaced ALI); moderate 100–200; severe <100. Causes: pneumonia, sepsis, aspiration, trauma, pancreatitis, blood transfusion (TRALI). Mortality: mild ~27%, moderate ~32%, severe ~45%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','easy','flashcard','In which two conditions is non-invasive ventilation (NIV/BiPAP) most strongly evidence-based?','["Acute hypercapnic exacerbation of COPD (pH 7.25–7.35, PaCO2 >6 kPa) and acute cardiogenic pulmonary oedema (CPAP rather than BiPAP)"]','A','NIV avoids complications of intubation (VAP, barotrauma). In COPD exacerbation, NIV reduces mortality, intubation rate and length of stay. In cardiogenic pulmonary oedema, CPAP rapidly improves oxygenation. NIV is contraindicated if patient is unable to protect airway.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','medium','flashcard','What is lung-protective ventilation in ARDS and what tidal volume is recommended?','["Tidal volume 6 mL/kg ideal body weight (not actual body weight), plateau pressure ≤30 cmH2O, PEEP titrated to minimise driving pressure — based on the ARMA trial"]','A','High tidal volumes cause volutrauma and biotrauma (cytokine release) — ventilator-induced lung injury (VILI). Driving pressure (plateau pressure − PEEP) <15 cmH2O is independently associated with improved survival. Permissive hypercapnia (PaCO2 up to 8–10 kPa) is acceptable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','medium','flashcard','What is the evidence for prone positioning in severe ARDS?','["PROSEVA trial: prone positioning ≥16 hours/day in moderate-severe ARDS (PaO2/FiO2 <150) reduced 28-day mortality from 32.8% to 16% (NNT ~6)"]','A','Prone positioning redistributes perfusion to better-ventilated ventral lung regions, reduces dorsal atelectasis and decreases VILI. Complications include pressure sores, accidental extubation, haemodynamic compromise. Prone positioning is now standard of care for PaO2/FiO2 <150.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','medium','flashcard','What is the role of dexamethasone in ARDS?','["Dexamethasone 20 mg IV for 5 days then 10 mg for 5 days in moderate-severe ARDS — DEXA-ARDS trial showed reduced duration of ventilation and 60-day mortality benefit"]','A','Dexamethasone modulates the dysregulated immune response in ARDS. COVID-19 ARDS also benefits from dexamethasone 6 mg/day (RECOVERY trial). Systemic corticosteroids reduce fibroproliferative phase but increase secondary infection risk if used late.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','medium','flashcard','What is high-flow nasal oxygen (HFNO/HFNC) and when is it used?','["HFNO delivers heated humidified oxygen at up to 60 L/min via wide-bore nasal prongs, providing FiO2 up to 1.0 and ~1 cmH2O PEEP per 10 L/min; used in hypoxaemic RF not responding to standard oxygen and as step-down from NIV"]','A','HFNO reduces work of breathing, washes out anatomical dead space and provides modest PEEP. The ROX index (SpO2/FiO2 ÷ RR) >4.88 at 12 hours predicts HFNO success (avoiding intubation). Not appropriate in hypercapnic RF — BiPAP preferred.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','medium','flashcard','What are the indications for emergency intubation and invasive mechanical ventilation?','["GCS ≤8 (inability to protect airway), refractory hypoxaemia (PaO2 <8 kPa despite high-flow O2/NIV), haemodynamic instability, exhaustion, rising PaCO2 despite optimal NIV, impending respiratory arrest"]','A','Intubation carries risks (VAP, barotrauma, haemodynamic instability on induction, tracheal injury) but is life-saving when indicated. Rapid sequence induction (RSI) with ketamine/rocuronium is standard. Always pre-oxygenate with 100% O2 for 3–5 minutes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','hard','flashcard','What is ventilator-induced lung injury (VILI) and what are its main mechanisms?','["VILI encompasses volutrauma (overdistension from high TV), barotrauma (high airway pressures), atelectrauma (repeated opening/closing of unstable alveoli) and biotrauma (systemic cytokine release from injured lung)"]','A','Atelectrauma is prevented by adequate PEEP to keep alveoli open throughout the respiratory cycle. Biotrauma can cause multiorgan dysfunction syndrome (MODS). Lung-protective ventilation (TV 6 mL/kg IBW, driving pressure <15 cmH2O) minimises all four mechanisms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','Respiratory System','Clinicals','Respiratory Failure & Mechanical Ventilation','hard','flashcard','What is permissive hypercapnia and when is it used in mechanical ventilation?','["Permissive hypercapnia: deliberately allowing PaCO2 to rise above normal (up to 8–10 kPa or ~70 mmHg) to achieve low tidal volumes and reduce VILI; used in ARDS and severe asthma ventilation"]','A','Hypercapnia causes cerebral vasodilation (avoid in raised ICP), pulmonary vasoconstriction, mild myocardial depression, acidosis (compensated by bicarbonate retention). Target pH >7.20 (not lower). In severe asthma, prolonged expiratory time (I:E 1:3 or 1:4) prevents dynamic hyperinflation (auto-PEEP).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');